package agent

import (
	"context"
	"errors"
	"strings"
	"testing"

	"github.com/alibaba/skill-up/internal/platform"
	"github.com/alibaba/skill-up/internal/runtime"
)

func TestNodeBootstrapLines(t *testing.T) {
	t.Parallel()

	cmd := strings.Join(nodeBootstrapLines("20"), "\n")
	for _, want := range []string{
		`NVM_DIR="${NVM_DIR:-$HOME/.nvm}"`,
		`NVM_SYMLINK_CURRENT=true`,
		`NVM_SOURCE="${NVM_SOURCE:-` + agentNVMSource + `}"`,
		`NVM_NODEJS_ORG_MIRROR="${NVM_NODEJS_ORG_MIRROR:-` + agentNodeMirror + `}"`,
		`npm_config_registry="${npm_config_registry:-${NPM_CONFIG_REGISTRY:-` + agentNPMRegistry + `}}"`,
		`agent_npm_prefix="${npm_config_prefix:-$HOME/.local}"`,
		`unset npm_config_prefix`,
		`export npm_config_prefix="$agent_npm_prefix"`,
		`export PATH="$npm_config_prefix/bin:$PATH"`,
		`if [ -s "$NVM_DIR/nvm.sh" ]; then . "$NVM_DIR/nvm.sh"; fi`,
		`node_major="$(node -p 'process.versions.node.split(".")[0]' 2>/dev/null || echo 0)"`,
		`[ "$node_major" -lt '20' ]`,
		"nvm install '20'",
		"nvm use '20'",
		"curl --connect-timeout '" + agentCurlConnectTimeout + "' --max-time '" + agentCurlMaxTime + "' -fsSL '" + agentNVMInstallURL + `' -o "$nvm_install_script" || curl --connect-timeout '` + agentCurlConnectTimeout + "' --max-time '" + agentCurlMaxTime + "' -fsSL '" + agentNVMFallbackURL + `' -o "$nvm_install_script"`,
		`command -v sha256sum`,
		`shasum -a 256 "$nvm_install_script"`,
		`[ "$nvm_install_sha256" != '` + agentNVMInstallSHA256 + `' ]`,
	} {
		if !strings.Contains(cmd, want) {
			t.Fatalf("node bootstrap command missing %q:\n%s", want, cmd)
		}
	}
}

func TestNodeBootstrapLinesUsesDefaultVersion(t *testing.T) {
	t.Parallel()

	cmd := strings.Join(nodeBootstrapLines(""), "\n")
	if !strings.Contains(cmd, "nvm install '"+agentNodeDefaultVersion+"'") {
		t.Fatalf("node bootstrap command does not use default version %s:\n%s", agentNodeDefaultVersion, cmd)
	}
}

func TestEnsureNodeRuntime_ScriptShape(t *testing.T) {
	t.Parallel()

	rt := &nodeBootstrapTestRuntime{result: runtime.ExecResult{ExitCode: 0}}
	if err := ensureNodeRuntime(context.Background(), rt, "claude", ExecOptions{}); err != nil {
		t.Fatalf("ensureNodeRuntime returned error: %v", err)
	}
	if len(rt.commands) != 1 {
		t.Fatalf("expected 1 Exec call, got %d: %v", len(rt.commands), rt.commands)
	}
	cmd := rt.commands[0]
	// The guard short-circuit must precede the bootstrap so it never executes
	// when the CLI is already on PATH.
	if !strings.HasPrefix(cmd, "set -e\nif command -v 'claude' >/dev/null 2>&1; then exit 0; fi\n") {
		t.Fatalf("bootstrap script missing CLI short-circuit at top:\n%s", cmd)
	}
	if !strings.Contains(cmd, "nvm install '"+agentNodeDefaultVersion+"'") {
		t.Fatalf("bootstrap script missing nvm install:\n%s", cmd)
	}
}

func TestEnsureNodeRuntime_WrapsExecError(t *testing.T) {
	t.Parallel()

	sentinel := errors.New("network down")
	rt := &nodeBootstrapTestRuntime{err: sentinel}
	err := ensureNodeRuntime(context.Background(), rt, "claude", ExecOptions{})
	if err == nil {
		t.Fatal("expected error")
	}
	if !errors.Is(err, sentinel) {
		t.Fatalf("expected wrapped sentinel error, got %v", err)
	}
	if !strings.Contains(err.Error(), "node bootstrap failed") {
		t.Fatalf("expected 'node bootstrap failed' prefix, got %v", err)
	}
}

func TestEnsureNodeRuntime_WrapsNonZeroExit(t *testing.T) {
	t.Parallel()

	rt := &nodeBootstrapTestRuntime{result: runtime.ExecResult{ExitCode: 7, Stderr: "checksum mismatch"}}
	err := ensureNodeRuntime(context.Background(), rt, "codex", ExecOptions{})
	if err == nil {
		t.Fatal("expected error")
	}
	if !strings.Contains(err.Error(), "node bootstrap failed") {
		t.Fatalf("expected 'node bootstrap failed' prefix, got %v", err)
	}
	if !strings.Contains(err.Error(), "checksum mismatch") {
		t.Fatalf("expected stderr to be surfaced, got %v", err)
	}
}

func TestEnsureNodeRuntime_RejectsEmptyCLIBin(t *testing.T) {
	t.Parallel()

	rt := &nodeBootstrapTestRuntime{}
	if err := ensureNodeRuntime(context.Background(), rt, "", ExecOptions{}); err == nil {
		t.Fatal("expected error when cliBin is empty")
	}
	if len(rt.commands) != 0 {
		t.Fatalf("expected no Exec calls when cliBin is empty, got %v", rt.commands)
	}
}

type nodeBootstrapTestRuntime struct {
	commands []string
	result   runtime.ExecResult
	err      error
}

func (r *nodeBootstrapTestRuntime) Create(context.Context) error { return nil }
func (r *nodeBootstrapTestRuntime) Close() error                 { return nil }
func (r *nodeBootstrapTestRuntime) Start(context.Context) error  { return nil }
func (r *nodeBootstrapTestRuntime) Stop(context.Context) error   { return nil }
func (r *nodeBootstrapTestRuntime) UploadFile(context.Context, string, string) error {
	return nil
}
func (r *nodeBootstrapTestRuntime) UploadDir(context.Context, string, string) error { return nil }
func (r *nodeBootstrapTestRuntime) DownloadFile(context.Context, string, string) error {
	return nil
}
func (r *nodeBootstrapTestRuntime) DownloadDir(context.Context, string, string) error { return nil }
func (r *nodeBootstrapTestRuntime) Exec(_ context.Context, command string, _ runtime.ExecOptions) (runtime.ExecResult, error) {
	r.commands = append(r.commands, command)
	return r.result, r.err
}
func (r *nodeBootstrapTestRuntime) Workspace() string            { return "/workspace" }
func (r *nodeBootstrapTestRuntime) RequiresProcessSandbox() bool { return false }
func (r *nodeBootstrapTestRuntime) MergeEnv(map[string]string)   {}
func (r *nodeBootstrapTestRuntime) Shell() platform.Shell {
	return platform.Shell{GOOS: platform.GOOSLinux, Family: platform.ShellPOSIX}
}

{
  "name": "skill-up-model-e2e-tools",
  "private": true,
  "version": "0.0.0",
  "dependencies": {
    "@anthropic-ai/claude-code": "2.1.217"
  }
}

package agent

import (
	"context"
	"errors"
	"fmt"
	"strings"
)

// errEnsureNodeRuntimeNoCLI is returned when ensureNodeRuntime is called
// without a CLI binary name to guard against — a programming error.
var errEnsureNodeRuntimeNoCLI = errors.New("ensureNodeRuntime: cliBin must not be empty")

const (
	agentNodeDefaultVersion = "22"
	agentCurlConnectTimeout = "5"
	agentCurlMaxTime        = "30"
	agentNVMInstallURL      = "https://raw.githubusercontent.com/nvm-sh/nvm/v0.40.2/install.sh"
	agentNVMFallbackURL     = "https://gitee.com/mirrors/nvm/raw/v0.40.2/install.sh"
	agentNVMInstallSHA256   = "a909fdd01765379ebc5983674adafb8bc9de6d928bfa188761309d4a0c36be0f"
	// agentNVMSource is the git clone source nvm uses for self-updates. Points
	// to the upstream GitHub repo; users in regions with limited access can
	// override via the NVM_SOURCE environment variable (e.g.
	// https://gitee.com/mirrors/nvm.git for mainland China).
	agentNVMSource = "https://github.com/nvm-sh/nvm.git"
	// agentNodeMirror is the default mirror for Node.js tarballs used by nvm.
	// Points to the official distribution; users in regions with limited access
	// can override via the NVM_NODEJS_ORG_MIRROR environment variable
	// (e.g. https://mirrors.aliyun.com/nodejs-release for mainland China).
	agentNodeMirror = "https://nodejs.org/dist"
	// agentNPMRegistry is the default npm registry. Points to the official
	// registry; users can override via npm_config_registry or NPM_CONFIG_REGISTRY
	// (e.g. https://registry.npmmirror.com for mainland China).
	agentNPMRegistry = "https://registry.npmjs.org"
)

func nodeBootstrapLines(nodeVersion string) []string {
	if nodeVersion == "" {
		nodeVersion = agentNodeDefaultVersion
	}
	return []string{
		`export NVM_DIR="${NVM_DIR:-$HOME/.nvm}"`,
		`export NVM_SYMLINK_CURRENT=true`,
		`export NVM_SOURCE="${NVM_SOURCE:-` + agentNVMSource + `}"`,
		`export NVM_NODEJS_ORG_MIRROR="${NVM_NODEJS_ORG_MIRROR:-` + agentNodeMirror + `}"`,
		`export npm_config_registry="${npm_config_registry:-${NPM_CONFIG_REGISTRY:-` + agentNPMRegistry + `}}"`,
		`agent_npm_prefix="${npm_config_prefix:-$HOME/.local}"`,
		`unset npm_config_prefix`,
		`if [ -s "$NVM_DIR/nvm.sh" ]; then . "$NVM_DIR/nvm.sh"; fi`,
		`node_major="$(node -p 'process.versions.node.split(".")[0]' 2>/dev/null || echo 0)"`,
		`case "$node_major" in ""|*[!0-9]*) node_major=0;; esac`,
		"if ! command -v npm >/dev/null 2>&1 || [ \"$node_major\" -lt " + shellQuote(nodeVersion) + " ]; then",
		"  if ! command -v nvm >/dev/null 2>&1; then",
		`    mkdir -p "$NVM_DIR"`,
		`    nvm_install_script="$(mktemp)"`,
		"    curl --connect-timeout " + shellQuote(agentCurlConnectTimeout) + " --max-time " + shellQuote(agentCurlMaxTime) + " -fsSL " + shellQuote(agentNVMInstallURL) + ` -o "$nvm_install_script" || curl --connect-timeout ` + shellQuote(agentCurlConnectTimeout) + " --max-time " + shellQuote(agentCurlMaxTime) + " -fsSL " + shellQuote(agentNVMFallbackURL) + ` -o "$nvm_install_script"`,
		`    if command -v sha256sum >/dev/null 2>&1; then nvm_install_sha256="$(sha256sum "$nvm_install_script" | awk '{print $1}')"; elif command -v shasum >/dev/null 2>&1; then nvm_install_sha256="$(shasum -a 256 "$nvm_install_script" | awk '{print $1}')"; else echo "sha256 checker not found" >&2; rm -f "$nvm_install_script"; exit 1; fi`,
		"    if [ \"$nvm_install_sha256\" != " + shellQuote(agentNVMInstallSHA256) + " ]; then echo \"nvm install checksum mismatch\" >&2; rm -f \"$nvm_install_script\"; exit 1; fi",
		`    bash "$nvm_install_script"`,
		`    rm -f "$nvm_install_script"`,
		`    . "$NVM_DIR/nvm.sh"`,
		"  fi",
		"  nvm install " + shellQuote(nodeVersion),
		"  nvm use " + shellQuote(nodeVersion),
		"fi",
		"if [ \"$node_major\" -lt " + shellQuote(nodeVersion) + " ] && command -v nvm >/dev/null 2>&1; then nvm use " + shellQuote(nodeVersion) + "; fi",
		`export npm_config_prefix="$agent_npm_prefix"`,
		`mkdir -p "$npm_config_prefix/bin"`,
		`export PATH="$npm_config_prefix/bin:$PATH"`,
	}
}

// ensureNodeRuntime runs the nvm/Node bootstrap as a standalone Exec call,
// separate from the agent invocation that follows. When cliBin is already on
// PATH the script short-circuits with `exit 0` and produces no output, so the
// happy-path cost is one extra `command -v` check. Errors are wrapped with a
// `node bootstrap failed` prefix so they're distinguishable from agent run
// failures in result handling and signal detectors.
func ensureNodeRuntime(ctx context.Context, rt Runtime, cliBin string, opts ExecOptions) error {
	if cliBin == "" {
		return errEnsureNodeRuntimeNoCLI
	}
	lines := []string{
		"set -e",
		"if command -v " + shellQuote(cliBin) + " >/dev/null 2>&1; then exit 0; fi",
	}
	lines = append(lines, nodeBootstrapLines(agentNodeDefaultVersion)...)
	script := strings.Join(lines, "\n")

	result, err := rt.Exec(ctx, script, opts)
	if err != nil {
		return fmt.Errorf("node bootstrap failed: %w", err)
	}
	if result.ExitCode != 0 {
		return fmt.Errorf("node bootstrap failed (exit %d): %s", result.ExitCode, result.Stderr)
	}
	return nil
}

